'use strict';
const CATEGORIES=['Lighting','Plumbing','Furniture','Wi-Fi & IT','Accessibility','Maintenance','Safety'];
const LOCATIONS=['Central Library','Science Block','Student Center','East Residence','Sports Complex','Main Walkway'];
const STATUSES=['Received','Under review','In progress','Resolved'];
const URGENCIES=['Low','Medium','High','Critical'];
const TEAMS=['Unassigned','Facilities','IT Services','Accessibility Office','Campus Safety'];
const KEY='campusfix-v1';
const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const agoDate=n=>new Date(Date.now()-n*86400000).toISOString();
const date=v=>new Date(v).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
const time=v=>new Date(v).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
const option=(arr,selected='',all='')=>(all?`<option value="">${all}</option>`:'')+arr.map(v=>`<option ${v===selected?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
let storageError='',route='overview',query='',filters={category:'',location:'',status:'',urgency:'',since:''};
let staff=false;try{staff=sessionStorage.getItem('campusfix-role')==='demo-staff'}catch{}
let commentCooldown=0;
function seed(){
 const rows=[
 ['Flickering lights on the second floor','Three ceiling lights near the quiet study area flicker continuously. It makes reading difficult in the evening.','Lighting','Central Library','High','In progress',27,27,false,false,'Facilities',2],
 ['Water leak near the chemistry lab','Water is dripping from the ceiling outside Lab 204. The floor is slippery; a temporary sign is in place.','Plumbing','Science Block','Critical','Under review',71,24,false,true,'Facilities',1],
 ['Ramp access blocked by stored equipment','Maintenance equipment is blocking the step-free entrance. Wheelchair users cannot enter through the accessible route.','Accessibility','Student Center','High','Received',51,57,true,false,'Accessibility Office',0],
 ['Wi-Fi keeps disconnecting in Block B','The campus Wi-Fi disconnects every few minutes in the common room, especially during afternoon classes.','Wi-Fi & IT','East Residence','Medium','In progress',81,67,false,false,'IT Services',3],
 ['Broken bench by the basketball court','One of the wooden slats is loose on the bench beside the outdoor court. Please repair before someone gets hurt.','Furniture','Sports Complex','Medium','Received',21,75,false,false,'Facilities',1],
 ['Pathway lighting restored','Two lights along the main walkway were out after sunset. Replacement bulbs have now been installed.','Lighting','Main Walkway','High','Resolved',48,38,false,false,'Facilities',6],
 ['Automatic door button not responding','The accessible entrance button does not open the east door. The manual door is heavy and difficult to operate.','Accessibility','Central Library','High','Under review',34,31,true,false,'Accessibility Office',2],
 ['Loose handrail on the north staircase','The handrail moves when pressure is applied. Please check the fixings on the staircase between floors 1 and 2.','Safety','Science Block','Critical','In progress',77,32,false,true,'Campus Safety',4],
 ['Study tables repaired in the reading room','Two wobbly tables near the windows have been repaired by the facilities team.','Furniture','Central Library','Low','Resolved',24,32,false,false,'Facilities',8],
 ['Drinking fountain needs servicing','The fountain beside the reception has very low water pressure.','Maintenance','Student Center','Low','Received',58,51,false,false,'Unassigned',1],
 ['Changing room tap fixed','A leaking tap in the ground-floor changing room has been replaced.','Plumbing','Sports Complex','Medium','Resolved',15,68,false,false,'Facilities',10],
 ['Network coverage improved in common room','The access point has been replaced and coverage is stable again.','Wi-Fi & IT','East Residence','Medium','Resolved',85,59,false,false,'IT Services',12]
 ];
 return {version:1,reports:rows.map((r,i)=>({id:`CF-${1042-i}`,title:r[0],description:r[1],category:r[2],location:r[3],urgency:r[4],status:r[5],x:r[6],y:r[7],accessibility:r[8],safety:r[9],team:r[10],created:agoDate(r[11]),name:i%3?'Anonymous':'Alex M.',due:r[5]==='Resolved'?'':new Date(Date.now()+3*86400000).toISOString().slice(0,10),photo:'',comments:[],history:[{status:'Received',at:agoDate(r[11]),actor:'CampusFix',note:'Report received and added to the campus queue.'},...(r[5]!=='Received'?[{status:r[5],at:agoDate(Math.max(0,r[11]-.5)),actor:r[10],note:r[5]==='Resolved'?'Repair completed and checked by the team. Thank you for reporting.':r[5]==='In progress'?'The assigned team is working on this issue.':'The team is reviewing the report and planning next steps.'}]:[])]})),following:[],preferences:{anonymous:true},nextId:1043};
}
function validData(d){return d&&d.version===1&&Array.isArray(d.reports)&&Array.isArray(d.following)&&d.preferences&&Number.isSafeInteger(d.nextId)&&d.reports.every(r=>typeof r.id==='string'&&typeof r.title==='string'&&typeof r.description==='string'&&CATEGORIES.includes(r.category)&&LOCATIONS.includes(r.location)&&STATUSES.includes(r.status)&&URGENCIES.includes(r.urgency)&&TEAMS.includes(r.team)&&Array.isArray(r.history)&&r.history.every(h=>h&&typeof h.status==='string'&&typeof h.at==='string')&&Array.isArray(r.comments)&&r.comments.every(c=>c&&typeof c.text==='string')&&Number.isFinite(r.x)&&Number.isFinite(r.y)&&r.x>=0&&r.x<=100&&r.y>=0&&r.y<=100&&!isNaN(Date.parse(r.created)))}
let data;
try{const raw=localStorage.getItem(KEY);data=raw?JSON.parse(raw):seed();if(!validData(data))throw Error('invalid');if(!raw)localStorage.setItem(KEY,JSON.stringify(data))}catch{data=seed();storageError='Saved data could not be loaded. A temporary sample is shown. Changes will only be saved after storage is available or you reset the demo.'}
function persist(next){try{if(storageError)throw Error('storage');localStorage.setItem(KEY,JSON.stringify(next));data=next;return true}catch{toast('Could not save. Browser storage may be full or unavailable. Remove the photo or free storage and try again.');return false}}
function change(fn){const next=structuredClone(data);fn(next);return persist(next)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000)}
function symbol(r){return r.category==='Lighting'?'☼':r.category==='Plumbing'?'♧':r.category==='Wi-Fi & IT'?'⌁':r.accessibility?'♿':r.category==='Furniture'?'▤':r.safety?'!':'⚒'}
function symbolClass(r){return r.category==='Plumbing'?'water':r.category==='Wi-Fi & IT'?'tech':r.accessibility?'access':''}
function badge(s){return `<span class="badge ${s==='In progress'?'progress':s==='Under review'?'review':s==='Resolved'?'resolved':'received'}">${s==='Resolved'?'✓':s==='In progress'?'◷':s==='Under review'?'◉':'○'} ${esc(s)}</span>`}
function flags(r){return `${r.safety?'<span class="badge safety">⚠ Immediate safety</span>':''}${r.accessibility?'<span class="badge accessibility">♿ Accessibility</span>':''}${r.urgency==='Critical'&&!r.safety?'<span class="badge urgent">! Critical</span>':''}`}
function card(r){return `<article class="report-card"><span class="report-symbol ${symbolClass(r)}" aria-hidden="true">${symbol(r)}</span><div class="report-body"><button class="report-title" data-open="${esc(r.id)}">${esc(r.title)}</button><div class="report-meta"><span>⌖ ${esc(r.location)}</span><span>·</span><span>${esc(r.category)}</span></div><div class="card-bottom">${badge(r.status)}${flags(r)}</div></div><div class="card-trailing">${date(r.created)}<button data-follow="${esc(r.id)}" aria-label="${data.following.includes(r.id)?'Unfollow':'Follow'} ${esc(r.id)}">${data.following.includes(r.id)?'♥':'♡'}</button></div></article>`}
function heading(title,desc,extra=''){return `<div class="page-heading"><div><div class="eyebrow">MAKE CAMPUS BETTER, TOGETHER</div><h1>${title}</h1><p>${desc}</p></div>${extra}</div>`}
function stats(){const counts=STATUSES.map(s=>data.reports.filter(r=>r.status===s).length);return `<div class="stats">${[['Total reports',data.reports.length,'Every voice makes a difference','▤'],['In progress',counts[2],'Our teams are on it','◷'],['Resolved',counts[3],'A better campus, one fix at a time','✓'],['Needs attention',counts[0]+counts[1],'Received & under review','⚑']].map(s=>`<div class="stat"><div class="stat-label">${s[0]}</div><span class="stat-icon">${s[3]}</span><div class="stat-value">${String(s[1]).padStart(2,'0')}</div><div class="stat-note">${s[2]}</div></div>`).join('')}</div>`}
function campusSvg(){return `<svg class="campus-svg" viewBox="0 0 600 420" preserveAspectRatio="none" role="img" aria-label="Sample Northwood campus layout with labeled buildings"><rect width="600" height="420" fill="#eff2e7"/><path d="M0 170 H600 M0 300 H600 M270 0 V420 M440 0 V420" stroke="#fffef8" stroke-width="28" fill="none"/><path d="M0 170 H600 M0 300 H600 M270 0 V420 M440 0 V420" stroke="#dfe5d6" stroke-width="1" fill="none"/><path d="M305 0 V420 M0 195 H600" stroke="#dce4d1" stroke-dasharray="4 5" fill="none"/><rect x="84" y="64" width="125" height="72" rx="5" fill="#d6ddc9" stroke="#c9d2bd"/><rect x="360" y="55" width="112" height="72" rx="5" fill="#d6ddc9" stroke="#c9d2bd"/><rect x="265" y="207" width="104" height="70" rx="5" fill="#d8decc" stroke="#c9d2bd"/><rect x="478" y="226" width="85" height="91" rx="5" fill="#d9dfcf" stroke="#c9d2bd"/><rect x="62" y="273" width="108" height="71" rx="5" fill="#dae3c8" stroke="#c8d6b8"/><rect x="72" y="283" width="88" height="50" rx="2" fill="none" stroke="#f4f6e9"/><path d="M116 283v50m-44-25h88" stroke="#f4f6e9"/><circle cx="116" cy="308" r="13" fill="none" stroke="#f4f6e9"/><circle cx="336" cy="109" r="26" fill="#dce7c9"/><circle cx="336" cy="109" r="13" fill="#e9efd9"/><g fill="#c6d7b2"><circle cx="32" cy="70" r="12"/><circle cx="51" cy="105" r="9"/><circle cx="218" cy="247" r="10"/><circle cx="386" cy="351" r="13"/><circle cx="407" cy="372" r="9"/><circle cx="545" cy="80" r="13"/><circle cx="562" cy="111" r="9"/><circle cx="44" cy="377" r="10"/><circle cx="203" cy="364" r="12"/></g><g font-family="Segoe UI,Arial,sans-serif" font-size="11" fill="#7f8c72" text-anchor="middle"><text x="146" y="111">Central Library</text><text x="414" y="101">Science Block</text><text x="317" y="250">Student Center</text><text x="520" y="282">East Residence</text><text x="117" y="364">Sports Complex</text><text x="183" y="188" font-size="9">MAIN WALKWAY</text><text x="337" y="150" font-size="8">CAMPUS GREEN</text></g><g transform="translate(559 352)"><circle r="20" fill="#fffef8" stroke="#dce3d2"/><path d="M0-12l-4 12h8z" fill="#849675"/><text y="12" text-anchor="middle" font-family="Arial" font-size="8" fill="#849675">N</text></g></svg>`}
function map(reports,pick=false){return `<div class="map-wrap ${pick?'pick-map':route==='map'?'full-map':''}" ${pick?'id="pick-map" tabindex="0" aria-label="Choose a pin position. Click or use arrow keys. Coordinates can also be entered below."':''}>${campusSvg()}${reports.map(r=>`<button type="button" class="map-pin ${r.status==='Resolved'?'resolved':r.safety||r.urgency==='Critical'?'critical':''} ${pick?'selected':''}" style="left:${Number(r.x)}%;top:${Number(r.y)}%" ${pick?'id="picked-pin" aria-label="Selected issue pin"':`data-open="${esc(r.id)}" aria-label="${esc(r.id)}: ${esc(r.title)}, ${esc(r.status)}"`}><span>${pick?'+':r.safety?'!':r.accessibility?'♿':r.status==='Resolved'?'✓':'•'}</span></button>`).join('')}</div>`}
function legend(){return '<div class="map-legend"><span><i></i> Open issue</span><span><i class="red"></i> Urgent / safety</span><span><i class="green"></i> Resolved</span></div>'}
function overview(){return heading('A better campus starts with you.','Spot an issue. Report it. Help us make a difference.',`<div class="date-chip">▦ ${date(new Date())}</div>`)+`<section class="hero"><div class="hero-content"><div class="eyebrow">YOUR CAMPUS. YOUR VOICE.</div><h2>See something?<br><em>Let’s get it fixed.</em></h2><p>From a flickering light to a blocked ramp, your report is the first step toward a safer, better campus.</p><button class="button lime" data-action="new">＋ Report an issue <span>↗</span></button></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 320 245"><circle cx="210" cy="125" r="110" fill="#2a5645"/><circle cx="210" cy="125" r="86" fill="none" stroke="#48705a" stroke-dasharray="3 7"/><path d="M25 230h285" stroke="#72916c"/><rect x="75" y="116" width="172" height="113" rx="2" fill="#a7bb8c"/><path d="M60 117l102-57 101 57z" fill="#d8e6b5"/><path d="M71 117h182v11H71z" fill="#bfd09f"/><g fill="#52745c"><path d="M94 145h17v27H94zM134 145h17v27h-17zM174 145h17v27h-17zM214 145h17v27h-17zM94 187h17v27H94zM214 187h17v27h-17z"/><path d="M149 192a14 14 0 0128 0v37h-28z"/></g><path d="M54 229v-55m-14 10c-13-18 5-45 15-42 18 6 29 39 11 45" fill="#6f986b" stroke="#6f986b"/><path d="M268 229v-37" stroke="#93ac78" stroke-width="4"/><circle cx="269" cy="177" r="22" fill="#92ad75"/><path d="M252 43c0-23 36-23 36 0 0 13-18 29-18 29s-18-16-18-29" fill="#d7ed97"/><circle cx="270" cy="42" r="7" fill="#375b41"/><path d="M56 70l5 7 13-16" stroke="#c7dc97" stroke-width="3" fill="none"/></svg></div></section>`+stats()+`<div class="content-grid"><section><div class="section-head"><div><h2>Recent reports</h2><p>A little awareness goes a long way.</p></div><a class="text-link" href="#reports">View all reports ↗</a></div><div class="panel"><div class="toolbar"><label class="search"><span class="screenreader">Search recent reports</span><input id="quick-search" placeholder="Search campus reports…"></label><a class="button secondary small" href="#reports">All reports ↗</a></div>${[...data.reports].sort((a,b)=>b.created.localeCompare(a.created)).slice(0,4).map(card).join('')}</div></section><aside><div class="section-head"><div><h2>Around your campus</h2><p>See where your voice makes an impact.</p></div></div><div class="panel panel-pad"><div class="mini-map-title">Campus activity <span>Sample campus</span></div>${map(data.reports.slice(0,6))}${legend()}<a class="text-link" href="#map" style="display:block;margin-top:19px">Explore the campus map ↗</a></div><div class="community-note"><h3>♿ A campus for everyone</h3><p>Accessibility matters. Flag barriers when reporting so our teams can prioritize inclusive access.</p><a href="#reports" data-access-filter>View accessibility reports →</a></div></aside></div><div class="bottom-note">♧ Every report is a step toward a campus that works for all of us.</div>`}
function filtered(){return [...data.reports].filter(r=>(route!=='following'||data.following.includes(r.id))&&(!query||`${r.id} ${r.title} ${r.description} ${r.location}`.toLowerCase().includes(query.toLowerCase()))&&(!filters.category||r.category===filters.category)&&(!filters.location||r.location===filters.location)&&(!filters.status||r.status===filters.status)&&(!filters.urgency||r.urgency===filters.urgency)&&(!filters.since||new Date(r.created)>=new Date(filters.since))).sort((a,b)=>b.created.localeCompare(a.created))}
function toolbar(){return `<div class="toolbar wide-toolbar"><label class="search"><span class="screenreader">Search reports</span><input id="search" placeholder="Search title, location or reference…" value="${esc(query)}"></label><label><span class="screenreader">Category</span><select data-filter="category">${option(CATEGORIES,filters.category,'All categories')}</select></label><label><span class="screenreader">Location</span><select data-filter="location">${option(LOCATIONS,filters.location,'All locations')}</select></label><label><span class="screenreader">Status</span><select data-filter="status">${option(STATUSES,filters.status,'All statuses')}</select></label><label><span class="screenreader">Urgency</span><select data-filter="urgency">${option(URGENCIES,filters.urgency,'All urgency')}</select></label><label class="field" style="font-size:9px;gap:3px">Reported since<input type="date" data-filter="since" value="${esc(filters.since)}" aria-label="Reported since date"></label><button class="button secondary small" data-action="clear">Reset filters</button></div>`}
function empty(){return `<div class="empty"><span>⌕</span><h3>${route==='following'?'Your follow list is quiet':'No reports found'}</h3><p>${route==='following'?'Follow a report to keep its progress close at hand.':'Try a different search or reset the filters.'}</p><button class="button secondary" data-action="clear">Reset filters</button> <a href="#reports" class="button">Browse reports</a></div>`}
function results(){const reports=filtered();return `<div class="filter-count" role="status">${reports.length} report${reports.length===1?'':'s'} ${route==='following'?'followed':'found'} · Demo data stored on this browser</div>${reports.length?(route==='map'?`<div class="map-layout panel-pad"><div>${map(reports)}${legend()}<div class="info-box">Sample campus layout — no map API or location tracking. Select any pin to open its report. Building names and positions are fictional.</div></div><div class="map-list">${reports.map(card).join('')}</div></div>`:reports.map(card).join('')):empty()}`}
function reportsPage(){return heading(route==='map'?'Your campus, at a glance.':route==='following'?'The issues you care about.':'Small reports. Real progress.',route==='following'?'Your followed reports and their latest updates.':'Explore what’s happening and see what’s getting fixed.',`<div class="view-toggle"><a class="${route!=='map'?'active':''}" href="#reports">☷ List</a><a class="${route==='map'?'active':''}" href="#map">⌖ Map</a></div>`)+toolbar()+`<section class="panel reports-panel list-only" id="results">${results()}</section>`}
function bars(title,values,field){const max=Math.max(1,...values.map(v=>data.reports.filter(r=>r[field]===v).length));return `<div class="panel"><h3>${title}</h3>${values.map(v=>{const n=data.reports.filter(r=>r[field]===v).length;return `<div class="bar-row"><span>${esc(v)}</span><div class="bar-track"><div class="bar-fill" style="width:${100*n/max}%"></div></div><b>${n}</b></div>`}).join('')}</div>`}
function staffPage(){if(!staff)return heading('A workspace for the fixers.','Review reports, coordinate teams, and keep your campus moving.')+`<section class="panel login-panel"><span class="avatar">▣</span><h2>Demo staff workspace</h2><p>Explore report management using a clearly labeled demo staff role. Student pages never show staff editing controls.</p><div class="info-box"><strong>Demo role, not secure authentication.</strong><br>This grants access to local sample data only. It requires no password and does not verify your identity. Production needs server-side login and authorization before handling real reports.</div><button class="button" data-action="staff-login">Enter as Demo Staff →</button><p><a class="text-link" href="#overview">← Back to student view</a></p></section>`;
 const week=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {label:d.toLocaleDateString('en-GB',{weekday:'short'}),n:data.reports.filter(r=>new Date(r.created).toDateString()===d.toDateString()).length}});
 return heading('Let’s keep campus moving.','Review, prioritize, and close the loop on campus issues.',`<button class="button secondary" data-action="staff-logout">Exit demo staff</button>`)+`<div class="staff-banner"><p><strong>DEMO STAFF ROLE</strong> · Local access only, no verified identity. All changes are saved to this browser and appear in the student report history.</p><span class="badge review">▣ Demo Staff</span></div>`+stats()+`<section class="analytics">${bars('Reports by category',CATEGORIES,'category')}${bars('Reports by location',LOCATIONS,'location')}<div class="panel"><h3>Reports by urgency</h3>${URGENCIES.map(u=>`<div class="bar-row"><span>${u==='Critical'?'⚠ ':''}${u}</span><div class="bar-track"><div class="bar-fill" style="width:${data.reports.filter(r=>r.urgency===u).length/data.reports.length*100||0}%"></div></div><b>${data.reports.filter(r=>r.urgency===u).length}</b></div>`).join('')}<h3 style="margin-top:23px">Incoming reports · last 7 days</h3><div class="trend">${week.map(d=>`<div class="trend-col"><div aria-label="${d.label}: ${d.n} reports" class="trend-bar" style="height:${Math.max(3,d.n/Math.max(1,...week.map(w=>w.n))*48)}px" title="${d.n} reports"></div>${d.label}<br>${d.n}</div>`).join('')}</div></div></section><div class="section-head"><div><h2>Report queue</h2><p>Select a report to manage its details and publish an update.</p></div></div>${toolbar()}<div class="panel reports-panel" id="results">${staffResults()}</div><div class="reset-line">Want a fresh presentation? <button data-action="reset">Reset demo data</button> (removes local reports, photos, comments, and follows)</div>`}
function staffResults(){const rows=filtered();return `<div class="filter-count" role="status">${rows.length} reports in this queue</div><div class="staff-row header"><span>REFERENCE</span><span>REPORT / LOCATION</span><span>STATUS</span><span class="priority-cell">PRIORITY</span><span class="team-cell">TEAM</span></div>${rows.length?rows.map(r=>`<div class="staff-row"><button class="text-link" data-manage="${r.id}">${r.id}</button><div><button class="report-title" data-manage="${r.id}">${esc(r.title)}</button><small>${esc(r.location)} ${r.accessibility?'· ♿ Accessibility':''} ${r.safety?'· ⚠ Safety':''}</small></div><span>${badge(r.status)}</span><span class="priority-cell">${r.urgency==='Critical'?'⚠ ':''}${r.urgency}</span><span class="team-cell">${esc(r.team)}</span></div>`).join(''):empty()}`}
function render(){route=location.hash.slice(1).split('/')[0]||'overview';if(!['overview','reports','map','following','staff'].includes(route)){location.hash='overview';return}document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===route);if(a.dataset.nav===route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('#nav-count').textContent=data.reports.length;$('#crumb').textContent={overview:'Overview',reports:'All reports',map:'Campus map',following:'Following',staff:'Staff workspace'}[route];$('#main').innerHTML=(storageError?`<div class="storage-alert" role="alert">${storageError}<button class="button secondary small" data-action="reset">Reset local demo</button></div>`:'')+(route==='overview'?overview():route==='staff'?staffPage():reportsPage());document.title=`CampusFix · ${$('#crumb').textContent}`;bindFilters()}
function updateResults(){if($('#results'))$('#results').innerHTML=route==='staff'&&staff?staffResults():results()}
function bindFilters(){const search=$('#search');if(search)search.addEventListener('input',e=>{query=e.target.value;updateResults()});document.querySelectorAll('[data-filter]').forEach(el=>el.addEventListener('change',()=>{filters[el.dataset.filter]=el.value;updateResults()}));$('#quick-search')?.addEventListener('keydown',e=>{if(e.key==='Enter'){query=e.target.value;location.hash='reports'}})}
const modal=$('#modal');let returnFocus=null;
function openModal(html){if(!modal.open)returnFocus=document.activeElement;modal.innerHTML=html;if(!modal.open)modal.showModal()}
function closeModal(){modal.close();if(returnFocus?.isConnected)returnFocus.focus()}
function modalHead(title,subtitle=''){return `<div class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="close" data-action="close" aria-label="Close dialog">×</button></div>`}
let picked={x:50,y:50};
function newReport(){picked={x:50,y:50};openModal(modalHead('Let’s get it fixed.','A minute of your time. A better campus for everyone.')+`<form id="report-form" class="modal-body"><div id="form-error" role="alert"></div><div class="form-grid"><label class="field wide">What’s the issue? *<input name="title" required minlength="5" maxlength="90" placeholder="e.g. Broken light outside the library" autofocus><small>Keep it short and specific (5–90 characters).</small></label><label class="field wide">Tell us a little more *<textarea name="description" required minlength="15" maxlength="1500" placeholder="What did you notice? Include details that will help the team find and fix it."></textarea></label><label class="field">Category *<select name="category" required><option value="">Choose a category</option>${option(CATEGORIES)}</select></label><label class="field">Building / location *<select name="location" id="building" required><option value="">Choose a location</option>${option(LOCATIONS)}</select></label><label class="field">Urgency *<select name="urgency">${option(URGENCIES,'Medium')}</select><small>Critical: needs immediate attention.</small></label><label class="field">Optional photo<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG, or WebP · maximum 1 MB. Avoid people or personal information.</small></label><div class="field wide">Pin the issue on campus *<p class="map-instruction">Choose a building to position the pin, then click the map to refine it. Keyboard: arrow keys or coordinates below.</p>${map([{...picked}],true)}<div class="map-keyboard"><label>Across % <input type="number" min="0" max="100" value="50" id="pin-x" aria-label="Pin across percentage" required></label><label>Down % <input type="number" min="0" max="100" value="50" id="pin-y" aria-label="Pin down percentage" required></label><span id="pin-readout" role="status">Pin: 50%, 50%</span></div></div><div class="field wide checkbox-row"><label class="check"><input name="accessibility" type="checkbox">♿ Affects accessibility</label><label class="check"><input name="safety" type="checkbox">⚠ Immediate safety concern</label></div><div class="field wide"><label class="check"><input type="checkbox" name="anonymous" id="anonymous" ${data.preferences.anonymous?'checked':''}>Submit anonymously</label><label class="field" id="name-field" ${data.preferences.anonymous?'hidden':''}>Display name *<input name="name" id="reporter-name" maxlength="50" placeholder="Your public display name" ${data.preferences.anonymous?'':'required'}></label></div><label class="field wide" style="display:none" aria-hidden="true">Leave this empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="info-box"><strong>Your privacy in this demo</strong><br>We store your report, chosen pin, optional photo, comments, follows, and anonymity preference in this browser. A display name is public if provided. No email, account, or device location is collected. Anonymous reports show “Anonymous”; photos and text may still identify you. No reports are sent to campus staff.<br><strong>Immediate danger?</strong> Contact your campus security or local emergency service directly. This demo is not monitored.</div><div class="form-actions"><small>* Required fields · Saved on this device only</small><button type="button" class="button secondary" data-action="close">Cancel</button><button class="button" type="submit">Submit report ↗</button></div></form>`);
 $('#anonymous').addEventListener('change',e=>{$('#name-field').hidden=e.target.checked;$('#reporter-name').required=!e.target.checked});
 $('#building').addEventListener('change',e=>{const points=[[27,27],[71,24],[51,57],[81,67],[21,75],[48,38]];const pos=points[LOCATIONS.indexOf(e.target.value)];if(pos)setPin(...pos)});
 $('#pick-map').addEventListener('click',e=>{const r=e.currentTarget.getBoundingClientRect();setPin((e.clientX-r.left)/r.width*100,(e.clientY-r.top)/r.height*100)});
 $('#pick-map').addEventListener('keydown',e=>{const d={ArrowLeft:[-2,0],ArrowRight:[2,0],ArrowUp:[0,-2],ArrowDown:[0,2]}[e.key];if(d){e.preventDefault();setPin(picked.x+d[0],picked.y+d[1])}});
 ['x','y'].forEach(k=>$('#pin-'+k).addEventListener('input',e=>{if(e.target.value!==''&&e.target.validity.valid)setPin(k==='x'?Number(e.target.value):picked.x,k==='y'?Number(e.target.value):picked.y)}));
 $('#report-form').addEventListener('submit',submitReport)
}
function setPin(x,y){picked={x:Math.round(Math.max(0,Math.min(100,x))),y:Math.round(Math.max(0,Math.min(100,y)))};$('#picked-pin').style.left=picked.x+'%';$('#picked-pin').style.top=picked.y+'%';$('#pin-x').value=picked.x;$('#pin-y').value=picked.y;$('#pin-readout').textContent=`Pin: ${picked.x}%, ${picked.y}%`}
function formError(id,msg){const node=$(id);node.innerHTML=`<div class="error">${esc(msg)}</div>`;node.scrollIntoView({block:'nearest'})}
function contentError(text){if(/https?:\/\/|www\./i.test(text))return 'Please remove links. For this demo, links are blocked to reduce spam.';if(/\b(fuck|shit|bitch|asshole)\b/i.test(text))return 'Please keep updates respectful and remove inappropriate language.';if(/(.)\1{12,}/.test(text))return 'Please remove repeated characters.';return ''}
async function submitReport(e){e.preventDefault();const form=e.currentTarget;const f=new FormData(form);const title=f.get('title').trim(),description=f.get('description').trim();const anonymous=f.has('anonymous');const name=anonymous?'Anonymous':f.get('name').trim();if(f.get('website'))return formError('#form-error','Your submission could not be accepted.');if(title.length<5||description.length<15||!name)return formError('#form-error','Add a title of at least 5 characters, a description of at least 15 characters, and a name unless anonymous.');const problem=contentError(title+' '+description+' '+name);if(problem)return formError('#form-error',problem);if(!CATEGORIES.includes(f.get('category'))||!LOCATIONS.includes(f.get('location'))||!URGENCIES.includes(f.get('urgency')))return formError('#form-error','Choose a valid category, location, and urgency.');const photo=f.get('photo');if(photo.size>1048576||photo.size&&!['image/jpeg','image/png','image/webp'].includes(photo.type))return formError('#form-error','Choose a JPG, PNG, or WebP image smaller than 1 MB.');const submit=$('button[type=submit]',form);submit.disabled=true;submit.textContent='Saving report…';let image='';try{if(photo.size)image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(photo)});const id=`CF-${data.nextId}`;const now=new Date().toISOString();const report={id,title,description,category:f.get('category'),location:f.get('location'),urgency:f.get('urgency'),status:'Received',team:'Unassigned',due:'',...picked,accessibility:f.has('accessibility'),safety:f.has('safety'),name,photo:image,created:now,comments:[],history:[{status:'Received',at:now,actor:'CampusFix',note:'Your report was received. The team can now review and assign it.'}]};if(!change(d=>{d.reports.unshift(report);d.nextId++;d.following.push(id);d.preferences.anonymous=anonymous})){formError('#form-error','Report was not saved. Storage may be unavailable or full. Try without a photo.');return}render();openModal(modalHead('Report received','Thank you for helping your campus.')+`<div class="modal-body success"><div class="success-icon">✓</div><h2>You reported it. We’ll track it.</h2><p>Your demo reference number</p><div class="reference">${id}</div><p>You’re automatically following this report.<br>Updates appear in Following on this browser. No email or push notifications are sent.</p><button class="button" data-open="${id}">View your report →</button><div class="info-box">Demo only: this report has not been sent to campus staff.</div></div>`);toast(`Report ${id} saved`)}catch{formError('#form-error','The photo could not be read. Choose another file or submit without a photo.')}finally{if(submit.isConnected){submit.disabled=false;submit.textContent='Submit report ↗'}}}
function detail(id){const r=data.reports.find(r=>r.id===id);if(!r)return toast('This report could not be found. Reset filters or refresh the page.');openModal(modalHead(esc(r.title),`${r.id} · Reported ${date(r.created)} by ${esc(r.name)}`)+`<div class="modal-body"><div class="detail-top">${badge(r.status)}${flags(r)}<span class="badge">${esc(r.urgency)} urgency</span><span class="badge">${esc(r.category)}</span></div><div class="detail-info"><div><small>LOCATION</small>${esc(r.location)}</div><div><small>ASSIGNED TEAM</small>${esc(r.team)}</div><div><small>ESTIMATED COMPLETION</small>${r.due?date(r.due+'T12:00:00'):'Not set'}</div></div><p class="detail-description">${esc(r.description)}</p>${r.photo&&/^data:image\/(jpeg|png|webp);base64,/.test(r.photo)?`<img class="detail-photo" src="${esc(r.photo)}" alt="Photo attached to ${esc(r.title)}">`:''}<div class="form-actions" style="margin-top:10px"><button class="button secondary" data-follow="${id}">${data.following.includes(id)?'♥ Following · Unfollow':'♡ Follow this report'}</button>${staff?`<button class="button" data-manage="${id}">Manage as Demo Staff ↗</button>`:''}</div><div class="progress-steps">${STATUSES.map((s,i)=>`<div class="step ${i<=STATUSES.indexOf(r.status)?'done':''}">${i<=STATUSES.indexOf(r.status)?'✓ ':''}${s}</div>`).join('')}</div><h3 class="subheading">Visible update history</h3><div class="timeline">${[...r.history].reverse().map(h=>`<div class="timeline-item"><strong>${esc(h.status)}</strong><small>${esc(h.actor)} · ${time(h.at)}</small><p>${esc(h.note)}</p></div>`).join('')}</div><h3 class="subheading">Community updates (${r.comments.length})</h3>${r.comments.map(c=>`<div class="comment"><small>${esc(c.name)} · ${time(c.at)}</small><p>${esc(c.text)}</p></div>`).join('')||'<p class="comment-rules">No updates yet. Have something useful to add?</p>'}<form id="comment-form" class="comment-form"><div id="comment-error" role="alert"></div><label class="field">Add a helpful update<textarea name="comment" required minlength="5" maxlength="600" placeholder="Share what you noticed or add useful details…"></textarea></label><label class="check"><input name="anonymous" type="checkbox" checked>Post anonymously</label><label class="field" id="comment-name-field" hidden>Display name<input name="name" maxlength="50"></label><div class="comment-rules">Be respectful. No personal details or links. Repeated posts, links, and basic profanity are blocked. Updates are public in this local demo.</div><button class="button" type="submit">Post update ↗</button></form></div>`);
 const form=$('#comment-form');form.elements.anonymous.addEventListener('change',e=>{$('#comment-name-field').hidden=e.target.checked;form.elements.name.required=!e.target.checked});form.addEventListener('submit',e=>{e.preventDefault();const text=form.elements.comment.value.trim(),anonymous=form.elements.anonymous.checked,name=anonymous?'Anonymous':form.elements.name.value.trim();const error=contentError(text+' '+name);if(error)return formError('#comment-error',error);if(text.length<5||!name)return formError('#comment-error','Add an update of at least 5 characters and a name unless anonymous.');if(Date.now()-commentCooldown<15000)return formError('#comment-error','Please wait 15 seconds between updates.');if(r.comments.some(c=>c.text.toLowerCase()===text.toLowerCase()))return formError('#comment-error','This update has already been posted.');if(change(d=>d.reports.find(x=>x.id===id).comments.push({text,name,at:new Date().toISOString()}))){commentCooldown=Date.now();detail(id);toast('Your update was added.')}})
}
function manage(id){if(!staff){closeModal();location.hash='staff';return}const r=data.reports.find(r=>r.id===id);if(!r)return toast('Report not found.');openModal(modalHead('Manage report',`${id} · Demo Staff · Changes are visible in student history`)+`<form id="manage-form" class="modal-body"><h3 style="font-size:16px;margin-top:0">${esc(r.title)}</h3><div id="manage-error" role="alert"></div><div class="form-grid"><label class="field">Status<select name="status">${option(STATUSES,r.status)}</select></label><label class="field">Priority / urgency<select name="urgency">${option(URGENCIES,r.urgency)}</select></label><label class="field">Category<select name="category">${option(CATEGORIES,r.category)}</select></label><label class="field">Assigned team<select name="team">${option(TEAMS,r.team)}</select></label><label class="field">Estimated completion date<input type="date" name="due" value="${esc(r.due)}"><small>Leave blank if not known. An estimate, not a guarantee.</small></label><label class="field wide">Public update *<textarea required minlength="8" maxlength="800" name="note" placeholder="Explain what changed and what students can expect next."></textarea></label></div><div class="info-box">Demo staff actions only change data in this browser. Real role enforcement must happen on a backend.</div><div class="form-actions"><button type="button" class="button secondary" data-open="${id}">View report</button><button type="submit" class="button">Save & publish update ↗</button></div></form>`);$('#manage-form').addEventListener('submit',e=>{e.preventDefault();if(!staff)return;const f=new FormData(e.currentTarget),note=f.get('note').trim();if(note.length<8)return formError('#manage-error','Add a public update with at least 8 characters.');const error=contentError(note);if(error)return formError('#manage-error',error);if(!STATUSES.includes(f.get('status'))||!URGENCIES.includes(f.get('urgency'))||!CATEGORIES.includes(f.get('category'))||!TEAMS.includes(f.get('team')))return formError('#manage-error','Choose valid report values.');const changed=['status','urgency','category','team','due'].filter(k=>r[k]!==f.get(k)).map(k=>`${{status:'Status',urgency:'Priority',category:'Category',team:'Team',due:'Estimate'}[k]}: ${r[k]||'Not set'} → ${f.get(k)||'Not set'}`);if(change(d=>{const current=d.reports.find(x=>x.id===id);['status','urgency','category','team','due'].forEach(k=>current[k]=f.get(k));current.history.push({status:current.status,at:new Date().toISOString(),actor:'Demo Staff',note:note+(changed.length?'\n'+changed.join(' · '):'')})})){render();detail(id);toast('Report updated. The public history is up to date.')}})}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]'),manageBtn=e.target.closest('[data-manage]'),follow=e.target.closest('[data-follow]'),action=e.target.closest('[data-action]');if(open)return detail(open.dataset.open);if(manageBtn)return manage(manageBtn.dataset.manage);if(follow){const id=follow.dataset.follow;if(change(d=>{d.following=d.following.includes(id)?d.following.filter(v=>v!==id):[...d.following,id]})){render();if(modal.open)detail(id);toast(data.following.includes(id)?'Following this report. Updates appear in Following.':'Report unfollowed.')}return}if(e.target.closest('[data-access-filter]')){filters.category='Accessibility';setTimeout(()=>{if(route==='reports')render()},0)}if(!action)return;switch(action.dataset.action){case 'new':newReport();break;case 'close':closeModal();break;case 'clear':query='';filters={category:'',location:'',status:'',urgency:'',since:''};render();break;case 'staff-login':staff=true;try{sessionStorage.setItem('campusfix-role','demo-staff')}catch{}render();toast('Demo Staff role active for this browser session.');break;case 'staff-logout':staff=false;try{sessionStorage.removeItem('campusfix-role')}catch{}render();toast('Demo staff session ended.');break;case 'reset':openModal(modalHead('Reset the local demo?','This cannot be undone.')+`<div class="modal-body"><p style="font-size:13px">Your reports, photos, updates, follows, and preferences on this browser will be replaced with fresh sample data.</p><div class="form-actions"><button class="button secondary" data-action="close">Keep my data</button><button class="button danger" data-action="confirm-reset">Reset demo data</button></div></div>`);break;case 'confirm-reset':try{const fresh=seed();localStorage.setItem(KEY,JSON.stringify(fresh));data=fresh;storageError='';query='';filters={category:'',location:'',status:'',urgency:'',since:''};closeModal();render();toast('Fresh demo data restored.')}catch{toast('Browser storage is unavailable. Enable it before resetting.')}break}});
window.addEventListener('hashchange',()=>{closeModal();render();window.scrollTo({top:0});$('#main').focus({preventScroll:true})});
window.addEventListener('storage',e=>{if(e.key===KEY){try{const next=JSON.parse(e.newValue);if(!validData(next))throw Error();data=next;storageError='';if(modal.open){closeModal();toast('Data changed in another tab. Reopen the report to see the latest version.')}render()}catch{storageError='Local demo data changed or was removed. Reset the demo to resume saving.';render()}}});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
render();
